status.windowCss:
#us-float, #us-prompt-bubble-window, .us-box, .hx-scroll {
  --us-float-bg: #2b2d2c;
  --us-float-fg: #dfe3dd;
  --us-float-border: #121413;
  --us-float-muted: #7b837d;
  --us-float-primary: #dfe3dd;
  --us-float-primary-fg: #1b201d;
  --us-float-secondary: #1b201d;
  --us-float-accent: #3a403c;
  scrollbar-color: #7b837d #1b201d !important;
  scrollbar-width: thin !important;
}
#us-float .us-f-title, #us-float .us-tab, #us-float .us-scene-button {
  font-family: 'Courier New', ui-monospace, monospace;
}
#us-float .us-tab {
  border-radius: 0 !important;
  padding: 4px 12px !important;
  margin: 0 2px !important;
}
#us-float .us-scene-button {
  border-radius: 0 !important;
}
#us-float ::-webkit-scrollbar, .us-box ::-webkit-scrollbar, .hx-scroll::-webkit-scrollbar, .hx-scroll ::-webkit-scrollbar {
  width: 6px !important;
  height: 6px !important;
}
#us-float ::-webkit-scrollbar-track, .us-box ::-webkit-scrollbar-track, .hx-scroll::-webkit-scrollbar-track, .hx-scroll ::-webkit-scrollbar-track {
  background: #1b201d !important;
}
#us-float ::-webkit-scrollbar-thumb, .us-box ::-webkit-scrollbar-thumb, .hx-scroll::-webkit-scrollbar-thumb, .hx-scroll ::-webkit-scrollbar-thumb {
  background: #7b837d !important;
  border-radius: 3px !important;
}
#us-float ::-webkit-scrollbar-thumb:hover, .us-box ::-webkit-scrollbar-thumb:hover, .hx-scroll::-webkit-scrollbar-thumb:hover, .hx-scroll ::-webkit-scrollbar-thumb:hover {
  background: #dfe3dd !important;
}
